 failed=[name for name,passed in row['checks'].items() if not passed]
 lines.append(f'- {row["pose"]} {"day" if row["blend"]=="000" else "night"}: '+('PASS all listed checks.' if not failed else '**UNMET:** '+', '.join(failed)+'.'))
