if (out/'soak-baseline/metrics.json').exists() and (out/'soak-works/metrics.json').exists():
 a=json.loads((out/'soak-baseline/metrics.json').read_text());b=json.loads((out/'soak-works/metrics.json').read_text());lines.append(f'\nMatched Works delta: {b["p95Ms"]-a["p95Ms"]:+.2f} ms. Control retains accepted AO, glow and final emission levels; water/road reflection, glint and the new emission-distance hook are disabled. No F-3D browser captures overlap the timed runs; concurrent work elsewhere on this shared host is uncontrolled.')
